(() => {
  document.querySelector('.company-more-menu')?.scrollIntoView({block:'center'});
  const remove = document.querySelector('.remove-company-btn');
  const r = remove.getBoundingClientRect();
  const x = r.left + r.width/2;
  const y = r.top + r.height/2;
  const topEl = document.elementFromPoint(x, y);
  return {
    viewport: {w: innerWidth, h: innerHeight},
    x, y,
    removeRect: {top: r.top, bottom: r.bottom, left: r.left, right: r.right},
    hit: topEl && (topEl.className || topEl.tagName),
    hitText: (topEl && topEl.textContent || '').trim().slice(0, 60),
