(() => {
  const card = document.querySelector('.company-card');
  const remove = document.querySelector('.remove-company-btn');
  card.scrollIntoView({block:'start'});
  const hit = (el) => {
    const r = el.getBoundingClientRect();
    const topEl = document.elementFromPoint(r.left + r.width/2, r.top + r.height/2);
    return {
      className: topEl && String(topEl.className),
      text: (topEl && topEl.textContent || '').trim().slice(0, 40),
      isRemove: !!(topEl && topEl.closest && topEl.closest('.remove-company-btn')),
    };
  };
  const withFix = { z: getComputedStyle(card).zIndex, ...hit(remove) };
  card.style.zIndex = 'auto';
  const withoutFix = { z: getComputedStyle(card).zIndex, ...hit(remove) };
  card.style.zIndex = '';
  const restored = { z: getComputedStyle(card).zIndex, ...hit(remove) };
  return { withFix, withoutFix, restored };
})()

(() => {
  const cards = document.querySelectorAll('.company-card');
  const openCard = cards[0];
  const nextCard = cards[1];
  const remove = document.querySelector('.remove-company-btn');
  const hit = () => {
    const r = remove.getBoundingClientRect();
    const topEl = document.elementFromPoint(r.left + r.width/2, r.top + r.height/2);
    return {
      className: topEl && String(topEl.className),
      text: (topEl && topEl.textContent || '').trim().slice(0, 50),
      isRemove: !!(topEl && topEl.closest && topEl.closest('.remove-company-btn')),
    };
  };
  openCard.style.zIndex = 'auto';
  openCard.style.transform = 'translateY(-3px)';
  const hoverNoRaise = hit();
  nextCard.style.transform = 'none';
  const hoverOpenOnly = hit();
  openCard.style.zIndex = '5';
  const hoverWithRaise = hit();
  openCard.style.transform = '';
  openCard.style.zIndex = '';
  nextCard.style.transform = '';
  return { hoverNoRaise, hoverOpenOnly, hoverWithRaise, restoredZ: getComputedStyle(openCard).zIndex };
})()

(() => {
  const jobs = document.getElementById('jobs');
  jobs?.scrollIntoView({block:'start'});
  const card = document.querySelector('.company-card');
  card?.scrollIntoView({block:'start'});
  return jobs ? jobs.getBoundingClientRect().top : 'nojobs';
})()

content.text:
The company `…` menu was painting **under the next card**. Hovering a card applies `transform`, which traps the menu in that card’s stacking context, so “Remove company” (and anything below the gap) sat behind the company underneath.

Fix: raise the open card, same pattern as the other popovers.

```7413:7419:relocation_jobs/static/styles.css
.company-more[open] {
  z-index: 30;
}

.company-card:has(.company-more[open]) {
  z-index: 5;
}
```

Hard-refresh the board if the old CSS is still cached (`styles.css?v=105`).

Skipped: portaling the menu to `document.body`. Add if a parent ever uses `overflow: hidden` and clips it anyway.
